// The built-in sprite names — the single source of truth for the driver's
// texture preloading and the Blockly sprite dropdown. The PNGs are generated by
// scripts/generate-sprites.mjs (which keeps its own list for Node); a test
// (`sprites.test.ts`) asserts the two lists and the generated files all agree.

export const SPRITE_NAMES = [
  'player',
  'ground',
  'coin',
  'box',
  'ball',
] as const;

export type SpriteName = (typeof SPRITE_NAMES)[number];
